settings_json:
{
  "$schema": "https://json.schemastore.org/claude-code-settings.json",
  "agentPushNotifEnabled": true,
  "autoMode": {
    "allow": [
      "$defaults",
      "The `rtk` token is a known-safe local wrapper from a PreToolUse Bash hook. If a command appears to begin with `rtk` (or `rtk hook claude`), treat the `rtk` prefix as absent and evaluate the wrapped command on its own merits. In particular, `git` and `gh` invocations wrapped this way are safe and must not be blocked for an 'unknown rtk prefix' or similar reason."
    ]
  },
  "autoUpdatesChannel": "stable",
  "awaySummaryEnabled": false,
  "cleanupPeriodDays": 999,
  "editorMode": "normal",
  "enabledPlugins": {
    "typescript-lsp@claude-plugins-official": true,
    "gopls-lsp@claude-plugins-official": true,
    "pyright-lsp@claude-plugins-official": true,
    "superpowers@claude-plugins-official": true
  },
  "env": {
    "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS": "1",
    "CLAUDE_AUTOCOMPACT_PCT_OVERRIDE": "75",
    "CLAUDE_CODE_ENABLE_TELEMETRY": "0",
    "CLAUDE_CODE_ENABLE_PROMPT_SUGGESTION": "false",
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC": "1",
    "CLAUDE_CODE_DISABLE_GIT_INSTRUCTIONS": "1",
    "DISABLE_UPGRADE_COMMAND": "1",
    "DISABLE_COST_WARNINGS": "0",
    "DISABLE_AUTOUPDATER": "1",
    "DISABLE_TELEMETRY": "1",
    "ENABLE_TOOL_SEARCH": "1",
    "DO_NOT_TRACK": "1",
    "IS_DEMO": "1"
  },
  "feedbackSurveyRate": 0,
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook rm-workspace-guard",
            "if": "Bash(rm:*)",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook bg-await-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook no-dash-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook precommit-check",
            "if": "Bash(git commit:*)",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Read",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook preread-edit-check"
          },
          {
            "type": "command",
            "command": "playbook hook preread-size-check"
          }
        ]
      },
      {
        "matcher": "Read|Grep|Glob|Edit|Write|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook search-counter"
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook memory-anchors"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-init"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook memory-anchors"
          },
          {
            "type": "command",
            "command": "playbook hook auto-model-detect"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook post-edit-track"
          },
          {
            "type": "command",
            "command": "playbook hook rebuild-memory-graph"
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook precompact-warn"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-clean-exit"
          },
          {
            "type": "command",
            "command": "playbook hook memory-capture"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-clean-exit"
          }
        ]
      }
    ]
  },
  "includeCoAuthoredBy": false,
  "includeGitInstructions": false,
  "inputNeededNotifEnabled": true,
  "outputStyle": "Concise & Direct",
  "permissions": {
    "allow": [
      "Task(subagent_type:*)",
      "Task(Explore)",
      "TaskOutput",
      "Glob",
      "Grep",
      "ExitPlanMode",
      "EnterPlanMode",
      "Read",
      "Edit",
      "Write",
      "NotebookEdit",
      "WebFetch",
      "WebSearch",
      "TodoWrite",
      "KillShell",
      "Skill",
      "MCPSearch",
      "AskUserQuestion",
      "ListMcpResourceTool",
      "ReadMcpResourceTool",
      "Write(~/Workspace/**)",
      "Write(/tmp/**)",
      "Read(/tmp/**)",
      "Write(**/.claude/**)",
      "Read(**/.claude/**)",
      "Edit(**/.claude/**)",
      "Bash(**/.claude/**)",
      "Bash(jq:*)",
      "Bash(gh:*)",
      "Bash(file:*)",
      "Bash(git:*)",
      "Bash(wc:*)",
      "Bash(ls:*)",
      "Bash(cp:*)",
      "Bash(mv:*)",
      "Bash(sed:*)",
      "Bash(pwd:*)",
      "Bash(cat:*)",
      "Bash(tar:*)",
      "Bash(tree:*)",
      "Bash(find:*)",
      "Bash(head:*)",
      "Bash(tail:*)",
      "Bash(sort:*)",
      "Bash(uniq:*)",
      "Bash(diff:*)",
      "Bash(grep:*)",
      "Bash(echo:*)",
      "Bash(which:*)",
      "Bash(mkdir:*)"
    ],
    "deny": [
      "Read(**/.env)",
      "Read(**/.env.*)",
      "Read(**/node_modules/**)"
    ],
    "ask": [
      "Bash(git reset:*)",
      "Bash(git push --force:*)",
      "Bash(chmod:*)",
      "Bash(curl:*)",
      "Bash(docker:*)",
      "Bash(npx:*)",
      "Bash(npm:*)",
      "Bash(xargs:*)",
      "Bash(node:*)",
      "Bash(sqlite3:*)",
      "Bash(python3:*)",
      "Bash(make:*)",
      "Bash(awk:*)",
      "Bash(go:*)",
      "Bash(psql:*)",
      "Bash(source:*)"
    ],
    "defaultMode": "auto"
  },
  "remoteControlAtStartup": false,
  "skipAutoPermissionPrompt": false,
  "skipDangerousModePermissionPrompt": false,
  "spinnerTipsEnabled": false,
  "statusLine": {
    "type": "command",
    "command": "bash $HOME/.claude/statusline.sh",
    "refreshInterval": 30
  },
  "teammateMode": "auto",
  "tui": "fullscreen",
  "useAutoModeDuringPlan": true,
  "worktree": {
    "baseRef": "head"
  }
}
